function receiptChatPhoto(update) {
  const message = update?.message,
    list = message?.photo;
  if (!Array.isArray(list) || !list.length) return { photo: false };
  const size = list[3] ?? list.at(-1);
  if (
    !Number.isSafeInteger(message.chat?.id) ||
    message.chat.id === 0 ||
    !Number.isSafeInteger(message.message_id) ||
    message.message_id < 1 ||
    !Number.isSafeInteger(message.date) ||
    message.date < 1 ||
    message.date > 253402214399 ||
    typeof size?.file_id !== "string" ||
    !/^[-_a-z0-9]{1,512}$/i.test(size.file_id) ||
    typeof size.file_unique_id !== "string" ||
    !/^[-_a-z0-9]{1,256}$/i.test(size.file_unique_id) ||
    (size.file_size != null &&
      (!Number.isSafeInteger(size.file_size) || size.file_size < 1 || size.file_size > 1024 * 1024))
  ) {
    throw Error("Telegram did not provide a supported receipt photo.");
  }
  const thread =
    Number.isSafeInteger(message.message_thread_id) && message.message_thread_id > 0
      ? message.message_thread_id
      : null;
  return {
    photo: true,
    chatId: String(message.chat.id),
    messageId: message.message_id,
    thread,
    receivedDate: new Date(message.date * 1000).toISOString().slice(0, 10),
    fileId: size.file_id,
    uniqueId: size.file_unique_id,
    expectedSize: size.file_size ?? 0,
  };
}
export default ({ event, config }) => {
  const photo = receiptChatPhoto(event.body);
  return {
    photo,
    allowed: photo.photo && config.allowedChats.includes(photo.chatId),
    request: { file_id: photo.fileId ?? "" },
  };
};

