function checkedReceipt(reply, categories, units, receivedDate, defaultCurrency, currencies) {
  const candidate = reply?.candidates?.[0];
  if (reply?.candidates?.length !== 1 || candidate?.finishReason !== "STOP")
    throw Error("Gemini did not return a complete receipt.");
  const parts = candidate.content?.parts?.filter((p) => p.thought !== true);
  if (parts?.length !== 1 || typeof parts[0].text !== "string")
    throw Error("Gemini did not return receipt JSON.");
  const receipt = JSON.parse(parts[0].text);
  const date = receipt?.date ?? receivedDate,
    mark = receipt?.currencyMark;
  if (
    typeof date !== "string" ||
    !/^\d{4}-\d\d-\d\d$/.test(date) ||
    !Number.isFinite(Date.parse(date)) ||
    new Date(date).toISOString().slice(0, 10) !== date ||
    !Array.isArray(receipt.lines) ||
    !receipt.lines.length ||
    receipt.lines.length > 20
  ) {
    throw Error("A readable receipt date and one to twenty line items are required.");
  }
  const currency =
    mark === "Rp"
      ? "IDR"
      : mark === "€"
        ? "EUR"
        : mark == null || mark === "$"
          ? defaultCurrency
          : mark;
  if (!currencies.includes(currency))
    throw Error("An explicit supported receipt currency or configured default is required.");
  const lines = receipt.lines.map((row) => {
    if (
      typeof row?.name !== "string" ||
      !row.name.trim() ||
      row.name.length > 140 ||
      !Number.isSafeInteger(row.quantity) ||
      row.quantity < 1 ||
      row.quantity > 100000 ||
      !categories.includes(row.category)
    ) {
      throw Error("A receipt line is missing its name, quantity or category.");
    }
    return {
      name: row.name.trim(),
      quantity: row.quantity,
      price: units(row.price),
      total: units(row.total),
      tax: row.tax === null ? null : units(row.tax),
      category: row.category,
    };
  });
  return {
    date,
    currency,
    total: units(receipt.receiptTotal),
    tax: receipt.receiptTax === null ? null : units(receipt.receiptTax),
    lines,
  };
}
function amountUnits(value) {
  if (typeof value !== "string" || !/^\d{1,10}(?:\.\d{1,3})?$/.test(value))
    throw Error("The receipt amount is missing or ambiguous.");
  const [whole, part = ""] = value.split(".");
  return Number(whole) * 1000 + Number(part.padEnd(3, "0"));
}
