function receiptRows(receipt, key) {
  const text = (content) => [{ type: "text", text: { content } }];
  return receipt.lines.map((row, index) => ({
    Name: { title: text(row.name) },
    Quantity: { number: row.quantity },
    Price: { number: row.price / 1000 },
    Total: { number: row.total / 1000 },
    Tax: { number: row.tax === null ? null : row.tax / 1000 },
    Category: { select: { name: row.category } },
    Date: { date: { start: receipt.date } },
    Currency: { rich_text: text(receipt.currency) },
    "Receipt Key": { rich_text: text(key) },
    Line: { number: index + 1 },
    "Receipt Lines": { number: receipt.lines.length },
  }));
}
function checkedNotionExpense(page, sourceId, key, line, expected) {
  const p = page?.properties,
    rich = p?.["Receipt Key"]?.rich_text;
  const stored =
    Array.isArray(rich) && rich.map((x) => x.plain_text ?? x.text?.content ?? "").join("");
  if (
    page?.object !== "page" ||
    typeof page.id !== "string" ||
    !page.id ||
    page.parent?.data_source_id?.toLowerCase().replace(/-/g, "") !== sourceId ||
    stored !== key ||
    p?.Line?.number !== line
  ) {
    throw Error("Notion did not confirm the row for this receipt.");
  }
  const text = (parts) =>
    parts?.map((part) => part.plain_text ?? part.text?.content ?? "").join("");
  if (
    text(p.Name?.title) !== text(expected.Name.title) ||
    text(p.Currency?.rich_text) !== text(expected.Currency.rich_text) ||
    p.Date?.date?.start !== expected.Date.date.start ||
    p.Category?.select?.name !== expected.Category.select.name ||
    ["Quantity", "Price", "Total", "Tax", "Receipt Lines"].some(
      (field) => p[field]?.number !== expected[field].number,
    )
  ) {
    throw Error("Notion confirmed unexpected receipt values.");
  }
  return page.id;
}
function expenseNotice(receipt) {
  const currency = receipt.currency;
  const names = receipt.lines.map((row) => row.quantity + " × " + row.name).join(", ");
  return (
    "Saved " +
    receipt.date +
    " receipt · " +
    currency +
    " " +
    receipt.total / 1000 +
    "\n" +
    names +
    (receipt.tax === null ? "" : "\nPrinted tax: " + currency + " " + receipt.tax / 1000)
  );
}
function telegramReceipt(message, chatId) {
  if (
    !Number.isSafeInteger(message?.message_id) ||
    message.message_id < 1 ||
    String(message?.chat?.id) !== chatId
  ) {
    throw new Error("Telegram did not confirm this chat reply");
  }
  return { chatId, messageId: String(message.message_id) };
}
export default async ({ body, status, photo, config }, context) => {
  if (status !== 200) throw Error("Gemini rejected the receipt image.");
  const receipt = checkedReceipt(
    body,
    expenseCategories(),
    amountUnits,
    photo.receivedDate,
    config.defaultCurrency,
    expenseCurrencies(),
  );
  const key = "telegram-receipt:" + photo.chatId + ":" + photo.uniqueId,
    state = config.dataSourceId + ":" + key;
  const rows = receiptRows(receipt, key);
  if (!(await context.state.insert(state, { status: "notion-pending" }))) return { saved: false };
  const ids = [];
  for (const [i, properties] of rows.entries()) {
    const created = await context.actions.call("notion.create_page", {
      parent: { type: "data_source_id", data_source_id: config.dataSourceId },
      properties,
    });
    ids.push(checkedNotionExpense(created, config.dataSourceId, key, i + 1, properties));
  }
  if (new Set(ids).size !== rows.length) throw Error("Notion returned duplicate page IDs.");
  await context.state.set(state, { status: "reply-pending", ids });
  const reply = await context.actions.call("telegram.send_message", {
    chatId: photo.chatId,
    text: expenseNotice(receipt),
    ...(photo.thread ? { messageThreadId: photo.thread } : {}),
    replyToMessageId: photo.messageId,
    disableWebPagePreview: true,
  });
  const confirm = telegramReceipt({ chat: reply.chat, message_id: reply.messageId }, photo.chatId);
  await context.state.set(state, { status: "saved", ids, messageId: confirm.messageId });
  return { saved: true };
};

