function expenseWindow(timestamp) {
  const until = Date.parse(timestamp);
  if (!Number.isFinite(until)) throw Error("A valid scheduled time is required.");
  const end = new Date(until).toISOString(),
    start = new Date(until - 7 * 86400000).toISOString();
  return {
    start,
    end,
    filter: {
      and: [
        { timestamp: "created_time", created_time: { on_or_after: start } },
        { timestamp: "created_time", created_time: { before: end } },
      ],
    },
  };
}
export default ({ event }) => ({ window: expenseWindow(event.scheduledAt) });

