function expenseSummary(pages, sourceId, window, categories, units) {
  const groups = new Map();
  for (const page of pages) {
    const p = page?.properties,
      text = (key) =>
        p?.[key]?.rich_text?.map((x) => x.plain_text ?? x.text?.content ?? "").join("");
    const key = text("Receipt Key");
    if (!key?.startsWith("telegram-receipt:")) continue;
    const count = p["Receipt Lines"]?.number,
      index = p.Line?.number,
      currency = text("Currency"),
      category = p.Category?.select?.name;
    const created = Date.parse(page.created_time);
    if (
      page.object !== "page" ||
      page.parent?.data_source_id?.toLowerCase().replace(/-/g, "") !== sourceId ||
      !Number.isFinite(created) ||
      created < Date.parse(window.start) ||
      created >= Date.parse(window.end) ||
      !Number.isSafeInteger(count) ||
      count < 1 ||
      count > 20 ||
      !Number.isSafeInteger(index) ||
      index < 1 ||
      index > count ||
      !/^[A-Z]{3}$/.test(currency) ||
      !categories.includes(category) ||
      typeof p.Total?.number !== "number"
    ) {
      throw Error("Notion returned an invalid expense row.");
    }
    const line = { category, amount: units(String(p.Total.number)) };
    const group = groups.get(key) ?? { count, currency, lines: new Map() };
    const prior = group.lines.get(index);
    if (
      group.count !== count ||
      group.currency !== currency ||
      (prior && (prior.category !== line.category || prior.amount !== line.amount))
    ) {
      throw Error("Notion returned conflicting rows for a receipt.");
    }
    group.lines.set(index, line);
    groups.set(key, group);
  }
  const sums = new Map();
  for (const group of groups.values()) {
    if (group.lines.size !== group.count) continue;
    const total = sums.get(group.currency) ?? new Map();
    for (const { category, amount } of group.lines.values()) {
      const next = (total.get(category) ?? 0) + amount;
      if (!Number.isSafeInteger(next))
        throw Error("The report amount exceeds the supported range.");
      total.set(category, next);
    }
    sums.set(group.currency, total);
  }
  return [...sums]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([currency, total]) => {
      const labels = categories.filter((category) => total.has(category));
      return {
        currency,
        caption:
          "Spending by category · " +
          currency +
          " · " +
          window.start.slice(0, 10) +
          " to " +
          window.end.slice(0, 10) +
          " UTC",
        chart: {
          type: "bar",
          data: {
            labels,
            datasets: [
              {
                label: "Spending (" + currency + ")",
                data: labels.map((label) => total.get(label) / 1000),
                backgroundColor: "#315EAA",
              },
            ],
          },
          options: { scales: { y: { beginAtZero: true } } },
        },
      };
    });
}
