  if (typeof value !== "string" || !/^\d{1,10}(?:\.\d{1,3})?$/.test(value))
    throw Error("The receipt amount is missing or ambiguous.");
  const [whole, part = ""] = value.split(".");
  return Number(whole) * 1000 + Number(part.padEnd(3, "0"));
}
