export default async ({ config, window }, context) => {
  const pages = [],
    seen = new Set();
  let cursor;
  for (let i = 0; i < 20; i++) {
    const reply = await context.actions.call("notion.query_data_source", {
      dataSourceId: config.dataSourceId,
      filter: window.filter,
      pageSize: 100,
      ...(cursor ? { startCursor: cursor } : {}),
    });
    if (!Array.isArray(reply?.results) || typeof reply.has_more !== "boolean")
      throw Error("Notion returned an incomplete ledger page.");
    pages.push(...reply.results);
    if (!reply.has_more)
      return {
        charts: expenseSummary(
          pages,
          config.dataSourceId,
          window,
          expenseCategories(),
          amountUnits,
        ),
      };
    cursor = reply.next_cursor;
    if (typeof cursor !== "string" || !cursor || seen.has(cursor))
      throw Error("Notion returned an invalid pagination cursor.");
    seen.add(cursor);
  }
  throw Error("The seven-day report exceeded 20 Notion pages.");
};

