function telegramReceipt(message, chatId) {
  if (
    !Number.isSafeInteger(message?.message_id) ||
    message.message_id < 1 ||
    String(message?.chat?.id) !== chatId
  ) {
    throw new Error("Telegram did not confirm this chat reply");
  }
  return { chatId, messageId: String(message.message_id) };
}
export default async ({ charts, config, window, token }, context) => {
  if (!/^\d{5,20}:[A-Za-z0-9_-]{20,100}$/.test(token))
    throw Error("Configure the Telegram report bot token.");
  let sent = 0;
  for (const chart of charts) {
    const { url } = await context.actions.call("quickchart.build_chart_url", {
      chart: chart.chart,
      format: "png",
      version: "4",
      width: 680,
      height: 380,
    });
    if (
      typeof url !== "string" ||
      !url.startsWith("https://quickchart.io/chart?") ||
      url.length > 5000
    )
      throw Error("QuickChart did not produce its chart URL.");
    const key = JSON.stringify([
      "expense-report",
      config.dataSourceId,
      config.reportChatId,
      config.reportThread,
      window.end,
      chart.currency,
    ]);
    if (!(await context.state.insert(key, { status: "send-pending" }))) continue;
    let result;
    try {
      const response = await context.fetch("https://api.telegram.org/bot" + token + "/sendPhoto", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          chat_id: config.reportChatId,
          ...(config.reportThread === null ? {} : { message_thread_id: config.reportThread }),
          caption: chart.caption,
          photo: url,
          protect_content: true,
        }),
      });
      if (response.status === 200) result = await response.json();
    } catch {}
    if (
      result?.ok !== true ||
      (config.reportThread !== null && result.result?.message_thread_id !== config.reportThread)
    )
      throw Error("Telegram did not confirm the configured report destination.");
    const receipt = telegramReceipt(result.result, config.reportChatId);
    await context.state.set(key, { status: "sent", messageId: receipt.messageId });
    sent++;
  }
  return { sent };
};
